72	bool TikcppBaseCheck::CheckTensorOverflowHigh(
73	    const uint32_t dtypeSize, const uint64_t bufferSize, const uint32_t calCount, const std::string& tensorName) const
74	{
75	    uint64_t needSize = static_cast<uint64_t>(dtypeSize * calCount);
76	    if (Int4Setter::Instance().GetInt4()) {
77	        needSize = static_cast<uint64_t>(calCount / INT4_TWO);
78	        Int4Setter::Instance().ResetInt4();
79	    }
80	    ASCENDC_CHECK(CheckTensorSizeOverflow(needSize, bufferSize, tensorName, apiName));
81	    return true;
82	}
