494	template <int bitNum, bool sign = true>
495	struct IntegerSubType {
496	    static int const kBits = bitNum;
497	    static bool const kSigned = sign;
498	
499	    using T = typename Conditional<kSigned, int8_t, uint8_t>::type;
500	    using Storage = uint8_t;
501	
502	    static Storage const mask = Storage(((static_cast<uint64_t>(1)) << static_cast<uint32_t>(kBits)) - 1);
503	    Storage storage;
504	    __aicore__ inline IntegerSubType() = default;
505	
506	    __aicore__ inline IntegerSubType(uint32_t value) : storage(reinterpret_cast<Storage const&>(value) & mask) {}
507	
508	    __aicore__ inline IntegerSubType(int32_t value) : storage(reinterpret_cast<Storage const&>(value) & mask) {}
509	
510	    __aicore__ inline operator T() const
511	    {
512	        if (kSigned && ((storage & Storage(static_cast<uint64_t>(1) << static_cast<uint32_t>(kBits - 1))) != 0)) {
513	            // Sign extend
514	            return T(storage) | ~T(mask);
515	        }
516	        return T(storage);
517	    }
518	
519	    __aicore__ inline bool operator==(IntegerSubType const& rhs) const { return storage == rhs.storage; }
520	
521	    __aicore__ inline bool operator!=(IntegerSubType const& rhs) const { return storage != rhs.storage; }
522	
523	    __aicore__ inline bool operator>(IntegerSubType const& rhs) const
524	    {
525	        bool lhsIsNeg = (this->storage & (static_cast<uint64_t>(1) << static_cast<uint32_t>(this->kBits - 1)));
526	        bool rhsIsNeg = (rhs.storage & (static_cast<uint64_t>(1) << static_cast<uint32_t>(rhs.kBits - 1)));
527	        if (kSigned && (lhsIsNeg != rhsIsNeg)) {
528	            return (!lhsIsNeg) && rhsIsNeg;
529	        }
530	        return this->storage > rhs.storage;
531	    }
532	
533	    __aicore__ inline bool operator>=(IntegerSubType const& rhs) const
534	    {
535	        bool lhsIsNeg = (this->storage & (static_cast<uint64_t>(1) << static_cast<uint32_t>(this->kBits - 1)));
536	        bool rhsIsNeg = (rhs.storage & (static_cast<uint64_t>(1) << static_cast<uint32_t>(rhs.kBits - 1)));
537	        if (kSigned && (lhsIsNeg != rhsIsNeg)) {
538	            return (!lhsIsNeg) && rhsIsNeg;
539	        }
540	        return storage >= rhs.storage;
541	    }
542	
543	    __aicore__ inline bool operator<(IntegerSubType const& rhs) const { return !(*this >= rhs); }
544	
545	    __aicore__ inline bool operator<=(IntegerSubType const& rhs) const { return !(*this > rhs); }
546	};
